CREATE TABLE `historial_estados` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ticket_id` int NOT NULL,
  `estado_anterior_id` smallint DEFAULT NULL,
  `estado_nuevo_id` smallint NOT NULL,
  `cambiado_por` int NOT NULL,
  `nota` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_historial_ticket_fecha` (`ticket_id`,`created_at`),
  KEY `fk_historial_estado_anterior` (`estado_anterior_id`),
  KEY `fk_historial_estado_nuevo` (`estado_nuevo_id`),
  KEY `fk_historial_usuario` (`cambiado_por`),
  CONSTRAINT `fk_historial_estado_anterior` FOREIGN KEY (`estado_anterior_id`) REFERENCES `estados` (`id`),
  CONSTRAINT `fk_historial_estado_nuevo` FOREIGN KEY (`estado_nuevo_id`) REFERENCES `estados` (`id`),
  CONSTRAINT `fk_historial_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_historial_usuario` FOREIGN KEY (`cambiado_por`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24575 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
